cd /home/runner/work/flutter_agent_harness/flutter_agent_harness && python3 - <<'EOF'
import json, subprocess, re

diff = subprocess.run(['git','diff','main...HEAD'],capture_output=True,text=True).stdout

# build map: path -> set of added line numbers (RIGHT side)
added = {}
cur = None; old_ln = new_ln = 0
for line in diff.splitlines():
    if line.startswith('+++ b/'):
        cur = line[6:]; added[cur] = set()
    elif line.startswith('@@'):
        m = re.match(r'@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@', line)
        new_ln = int(m.group(1)) - 1
    elif cur and line.startswith('+') and not line.startswith('+++'):
        new_ln += 1; added[cur].add(new_ln)
    elif cur and line.startswith('-') and not line.startswith('---'):
        pass
    elif cur and line.startswith(' '):
        new_ln += 1

review = json.load(open('outputs/pr_review.json'))
for c in review['inlineComments']:
    ok = c['line'] in added.get(c['path'], set())
    print(('OK ' if ok else 'MISS ') + c['path'] + ':' + str(c['line']))
print('recommendation:', review['recommendation'])
EOF

