  List<String> _rewriteDdArgs(List<String> args, String cwd) =>
      args.map((arg) => _rewriteDdArg(arg, cwd)).toList();

  List<String> _rewritePositionalArgs(
    String command,
    List<String> args,
    String cwd,
  ) {
    final skipFlags = nonPathFlagValues[command] ?? const <String>{};
    final result = <String>[];
