    final usageError = parsed.usageError;
    if (usageError != null) {
      return _err('$usageError\n$pipUsageText', 2);
    }
    return switch (parsed.subcommand) {
      PipSubcommand.help => _ok(pipUsageText),
      PipSubcommand.version => _ok('pip 24.0 (Fa sandbox pip-lite)\n'),
